body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: #1a237e; /* Dark sky/navy background */
    color: #e0e0e0;
    margin: 0;
    padding: 0;
    line-height: 1.6;
}

.hero {
    background-color: #283593; /* Slightly lighter navy for contrast */
    padding: 60px 20px;
    text-align: center;
    border-bottom: 3px solid #42a5f5;
}

h1 {
    color: #ffffff;
    margin-bottom: 10px;
}

h1:hover {
    color: #b3e5fc;
}

.hero p {
    color: #b0bec5;
    font-size: 1.1em;
    margin-bottom: 25px;
}

.primary-btn {
    background-color: #ff9800; /* Strong accent color (orange/gold) */
    color: #1a237e;
    border: none;
    padding: 12px 25px;
    font-size: 1em;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s;
    font-weight: bold;
}

.primary-btn:hover {
    background-color: #ffb347;
}

.container {
    max-width: 900px;
    margin: 40px auto;
    padding: 0 20px;
}

#observationList h2 {
    color: #81d4fa;
    border-bottom: 2px solid #42a5f5;
    padding-bottom: 10px;
    margin-bottom: 20px;
}

.cards-container {
    display: grid;
    gap: 20px;
}

.observation-card {
    background-color: #303f9f; /* Dark card background */
    border-left: 5px solid #ff9800;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
    transition: transform 0.2s;
}

.observation-card:hover {
    transform: translateY(-3px);
}

.observation-card h3 {
    color: #ffffff;
    margin-top: 0;
}

.observation-card p {
    color: #e0e0e0;
    margin-bottom: 10px;
}

.observation-card .meta {
    font-size: 0.9em;
    color: #90caf9;
    border-top: 1px dashed #42a5f5;
    padding-top: 5px;
}

.form-section {
    background-color: #212641;
    padding: 25px;
    border-radius: 8px;
    margin-top: 30px;
    border: 1px solid #42a5f5;
}

.form-section h3 {
    color: #ffffff;
    margin-top: 0;
}

.form-group {
    margin-bottom: 15px;
}

.form-group label {
    display: block;
    margin-bottom: 5px;
    font-weight: bold;
}

.form-group input[type="text"], 
.form-group textarea {
    width: 100%;
